                            <li>обеспечение соблюдения законов и иных нормативных правовых актов в области персональных данных.<br><br></li>
                        </ol>
                    </li>
                    <li><span>Обработка Оператором моих персональных данных (на бумажных носителях, в информационных системах персональных данных и без использования средств автоматизации, а также смешанным способом) должна осуществляться в соответствии с требованиями Федерального закона от 27.07.2006 г. №152-ФЗ &laquo;О персональных данных&raquo;, Политики в отношении обработки персональных данных ООО "Пироги.Ру".</span></li>
                </ol>
                <ol start="4" type="1">
                    <li><span>Оператор вправе осуществлять обработку моих персональных данных следующими способами: сбор, запись, систематизация, накопление, хранение, уточнение (обновление, изменение), использование, передача (распространение, предоставление, доступ), обезличивание, блокирование, уничтожение.<br><br></span></li>
                    <li><span>Настоящее согласие вступает в силу с момента передачи моих персональных данных Оператору посредством заполнения форм на Сайте и действует до дня отзыва в письменной форме.<br><br></span></li>
                    <li><span>Настоящее согласие может быть отозвано письменным заявлением на e-mail biz@pirogi.ru, либо письменным уведомлением по адресу: 620109&nbsp;<span itemprop="addressLocality">Екатеринбург</span>,&nbsp;<span itemprop="streetAddress">ул Крауля, стр. 9а, офис 410.</span></span></li>
