    <div id="popupPrivacy" class="popup popup-text" style="display: none;">
        <div class="popup-header">Политика конфиденциальности</div><div class="popup-body">
            <div class="text-block">
                <h2>Политика в отношении обработки персональных данных</h2>
                <ol>
                    <li>
                        <p><strong> Общие положения и основные термины</strong></p>
                    </li>
                </ol>
                <p>Настоящая политика обработки персональных данных составлена в&nbsp;соответствии с&nbsp;требованиями Федерального закона от&nbsp;27.07.2006. №&nbsp;152-ФЗ &laquo;О&nbsp;персональных данных&raquo; (далее&nbsp;&mdash; Закон о&nbsp;персональных данных) и&nbsp;определяет порядок обработки персональных данных и&nbsp;меры по&nbsp;обеспечению безопасности персональных данных, предпринимаемые&nbsp;ООО "Пироги.Ру"&nbsp;(далее&nbsp;&mdash; Оператор).</p>
                <p>1.1. Оператор ставит своей важнейшей целью и&nbsp;условием осуществления своей деятельности соблюдение прав и&nbsp;свобод человека и&nbsp;гражданина при обработке его персональных данных, в&nbsp;том числе защиты прав на&nbsp;неприкосновенность частной жизни, личную и&nbsp;семейную тайну.</p>
                <p>1.2. Настоящая политика Оператора в&nbsp;отношении обработки персональных данных (далее&nbsp;&mdash; Политика) применяется ко&nbsp;всей информации, которую Оператор может получить о&nbsp;посетителях веб-сайта&nbsp;https://pirogi.ru.</p>
                <p>&nbsp;</p>
                <ol start="2">
                    <li><strong> Основные понятия, используемые в Политике</strong></li>
                </ol>
                <p><strong>2.1. Автоматизированная обработка персональных данных</strong>&nbsp;&ndash; обработка персональных данных с помощью средств вычислительной техники.</p>
                <p><strong>2.2.</strong>&nbsp;Блокирование персональных данных &ndash; временное прекращение обработки персональных данных (за исключением случаев, если обработка необходима для уточнения персональных данных).</p>
                <p><strong>2.3. Веб-сайт</strong>&nbsp;&ndash; совокупность графических и информационных материалов, а также программ для ЭВМ и баз данных, обеспечивающих их доступность в сети Интернет.</p>
                <p><strong>2.4. Информационная система персональных данных</strong>&nbsp;&mdash; совокупность содержащихся в базах данных персональных данных, и обеспечивающих их обработку информационных технологий и технических средств.</p>
                <p><strong>2.5.</strong>&nbsp;<strong>Обезличивание персональных данных</strong>&nbsp;&mdash; действия, в результате которых невозможно определить без использования дополнительной информации принадлежность персональных данных конкретному Пользователю или иному субъекту персональных данных.</p>
                <p><strong>2.6.&nbsp;Обработка персональных данных</strong>&nbsp;&ndash; любое действие (операция) или совокупность действий (операций), совершаемых с использованием средств автоматизации или без использования таких средств с персональными данными, включая сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, передачу (распространение, предоставление, доступ), обезличивание, блокирование, удаление, уничтожение персональных данных.</p>
                <p><strong>2.7. Оператор</strong>&nbsp;&ndash; государственный орган, муниципальный орган, юридическое или физическое лицо, самостоятельно или совместно с другими лицами организующие и (или) осуществляющие обработку персональных данных, а также определяющие цели обработки персональных данных, состав персональных данных, подлежащих обработке, действия (операции), совершаемые с персональными данными.</p>
                <p><strong>2.8. Персональные данные</strong>&nbsp;&ndash; любая информация, относящаяся прямо или косвенно к определенному или определяемому Пользователю данного сайта.</p>
                <p><strong>2.9.</strong>&nbsp;<strong>Персональные данные, разрешенные субъектом для распространения&nbsp;</strong>&nbsp;&ndash; персональные данные, доступ неограниченного круга лиц к которым предоставлен субъектом персональных данных путем дачи согласия на обработку персональных данных, разрешенных субъектом персональных данных для распространения в порядке, предусмотренном Законом о персональных данных (далее - персональные данные, разрешенные для распространения).</p>
                <p><strong>2.10.</strong>&nbsp;<strong>Пользователь&nbsp;</strong>&ndash; любой посетитель этого сайта.</p>
                <p><strong>2.11.</strong>&nbsp;<strong>Предоставление персональных данных&nbsp;</strong>&ndash; действия, направленные на раскрытие персональных данных определенному лицу или определенному кругу лиц.</p>
                <p><strong>2.12.</strong>&nbsp;<strong>Распространение персональных данных</strong>&nbsp;&ndash; любые действия, направленные на раскрытие персональных данных неопределенному кругу лиц (передача персональных данных) или на ознакомление с персональными данными неограниченного круга лиц, в том числе обнародование персональных данных в средствах массовой информации, размещение в информационно-телекоммуникационных сетях или предоставление доступа к персональным данным каким-либо иным способом.</p>
                <p><strong>2.13. Трансграничная передача персональных данных</strong>&nbsp;&ndash; передача персональных данных на территорию иностранного государства органу власти иностранного государства, иностранному физическому или иностранному юридическому лицу.</p>
                <p><strong>2.14.</strong>&nbsp;<strong>Уничтожение персональных данных</strong>&nbsp;&ndash; любые действия, в результате которых персональные данные уничтожаются безвозвратно с невозможностью дальнейшего восстановления содержания персональных данных в информационной системе персональных данных и (или) уничтожаются материальные носители персональных данных.<br><br></p>
                <ol start="3">
                    <li><strong> Основные права и обязанности Оператора</strong></li>
                </ol>
                <p><strong>3.1. Оператор имеет право:</strong></p>
                <p><strong>3.1.1.</strong>&nbsp;Получать от субъекта персональных данных достоверные информацию и/или документы, содержащие персональные данные;</p>
                <p><strong>3.1.2.</strong>&nbsp;В&nbsp;случае отзыва субъектом персональных данных согласия на обработку персональных данных Оператор вправе продолжить обработку персональных данных без согласия субъекта персональных данных при наличии оснований, указанных в Законе о персональных данных;</p>
                <p><strong>3.1.3.</strong>&nbsp;Самостоятельно определять состав и перечень мер, необходимых и достаточных для обеспечения выполнения обязанностей, предусмотренных Законом о персональных данных и принятыми в соответствии с ним нормативными правовыми актами, если иное не предусмотрено Законом о персональных данных или другими федеральными законами.</p>
                <p><strong>3.2. Оператор обязан:</strong></p>
                <p><strong>3.2.1.</strong>&nbsp;Предоставлять субъекту персональных данных по его просьбе информацию, касающуюся обработки его персональных данных;</p>
                <p><strong>3.2.2.</strong>&nbsp;Организовывать обработку персональных данных в порядке, установленном действующим законодательством РФ;</p>
                <p><strong>3.2.3.</strong>&nbsp;Отвечать на обращения и запросы субъектов персональных данных и их законных представителей в соответствии с требованиями Закона о персональных данных;</p>
                <p><strong>3.2.4.</strong>&nbsp;Сообщать в уполномоченный орган по защите прав субъектов персональных данных по запросу этого органа необходимую информацию в течение 30 дней с даты получения такого запроса;</p>
                <p><strong>3.2.5.</strong>&nbsp;Публиковать или иным образом обеспечивать неограниченный доступ к настоящей Политике в отношении обработки персональных данных;</p>
                <p><strong>3.2.6.</strong>&nbsp;Принимать правовые, организационные и технические меры для защиты персональных данных от неправомерного или случайного доступа к ним, уничтожения, изменения, блокирования, копирования, предоставления, распространения персональных данных, а также от иных неправомерных действий в отношении персональных данных;</p>
                <p><strong>3.2.7.</strong>&nbsp;Прекратить передачу (распространение, предоставление, доступ) персональных данных, прекратить обработку и уничтожить персональные данные в порядке и случаях, предусмотренных Законом о персональных данных;</p>
                <p><strong>3.2.8.</strong>&nbsp;Исполнять иные обязанности, предусмотренные Законом о персональных данных.<br><br></p>
                <ol start="4">
                    <li><strong> Основные права и обязанности субъектов персональных данных</strong></li>
                </ol>
                <p><strong>4.1. Субъекты персональных данных имеют право:</strong></p>
                <p><strong>4.1.1.&nbsp;</strong>Получать информацию, касающуюся обработки его персональных данных, за исключением случаев, предусмотренных федеральными законами. Сведения предоставляются субъекту персональных данных Оператором в доступной форме, и в них не должны содержаться персональные данные, относящиеся к другим субъектам персональных данных, за исключением случаев, когда имеются законные основания для раскрытия таких персональных данных. Перечень информации и порядок ее получения установлен Законом о персональных данных;</p>
                <p><strong>4.1.2.</strong>&nbsp;Требовать от оператора уточнения его персональных данных, их блокирования или уничтожения в случае, если персональные данные являются неполными, устаревшими, неточными, незаконно полученными или не являются необходимыми для заявленной цели обработки, а также принимать предусмотренные законом меры по защите своих прав;</p>
                <p><strong>4.1.3.</strong>&nbsp;Выдвигать условие предварительного согласия при обработке персональных данных в целях продвижения на рынке товаров, работ и услуг;</p>
                <p><strong>4.1.4.</strong>&nbsp;На отзыв согласия на обработку персональных данных;</p>
                <p><strong>4.1.5</strong>. Обжаловать в уполномоченный орган по защите прав субъектов персональных данных или в судебном порядке неправомерные действия или бездействие Оператора при обработке его персональных данных;</p>
                <p><strong>4.1.6.</strong>&nbsp;На осуществление иных прав, предусмотренных законодательством РФ.</p>
                <p><strong>4.2. Субъекты персональных данных обязаны:</strong></p>
                <p><strong>4.2.1.</strong>&nbsp;Предоставлять Оператору достоверные данные о себе;</p>
                <p><strong>4.2.2.</strong>&nbsp;Сообщать Оператору об уточнении (обновлении, изменении) своих персональных данных.</p>
                <p><strong>4.3.&nbsp;</strong>Лица, передавшие Оператору недостоверные сведения о себе, либо сведения о другом субъекте персональных данных без согласия последнего, несут ответственность в соответствии с законодательством РФ.<br><br></p>
                <ol start="5">
                    <li><strong> Оператор может обрабатывать следующие персональные данные Пользователя</strong></li>
                </ol>
                <p><strong>5.1.</strong>&nbsp;Фамилия, имя, отчество</p>
                <p><strong>5.2.</strong>&nbsp;Электронный адрес</p>
                <p><strong>5.3.</strong>&nbsp;Номера телефонов</p>
                <p><strong>5.4.</strong>&nbsp;Также на сайте происходит сбор и обработка обезличенных данных о посетителях (файлов cookie, данных об устройстве, операционной системе и ее версии) с помощью сервисов интернет-статистики (Яндекс Метрика, Гугл Аналитика и других).</p>
                <p><strong>5.5.&nbsp;</strong>Вышеперечисленные данные далее по тексту Политики объединены общим понятием&nbsp;<strong>Персональные данные</strong>.</p>
                <p><strong>5.6.</strong>&nbsp;Обработка специальных категорий персональных данных, касающихся расовой, национальной принадлежности, политических взглядов, религиозных или философских убеждений, интимной жизни, Оператором не осуществляется.</p>
                <p><strong>5.7.&nbsp;</strong>Обработка персональных данных, разрешенных для распространения, из числа специальных категорий персональных данных, указанных в ч. 1 ст. 10 Закона о персональных данных, допускается, если соблюдаются запреты и условия, предусмотренные ст. 10.1 Закона о персональных данных.</p>
                <p><strong>5.8.&nbsp;</strong>Согласие Пользователя на обработку персональных данных, разрешенных для распространения, оформляется отдельно от других согласий на обработку его персональных данных. При этом соблюдаются условия, предусмотренные, в частности, ст. 10.1 Закона о персональных данных. Требования к содержанию такого согласия устанавливаются уполномоченным органом по защите прав субъектов персональных данных.</p>
                <p><strong>5.8.1.&nbsp;</strong>Согласие на обработку персональных данных, разрешенных для распространения, Пользователь предоставляет Оператору непосредственно.</p>
                <p><strong>5.8.2.</strong>&nbsp;Оператор обязан в срок не позднее трех рабочих дней с момента получения указанного согласия Пользователя опубликовать информацию об условиях обработки, о наличии запретов и условий на обработку неограниченным кругом лиц персональных данных, разрешенных для распространения.</p>
                <p><strong>5.8.3.</strong>&nbsp;Передача (распространение, предоставление, доступ) персональных данных, разрешенных субъектом персональных данных для распространения, должна быть прекращена в любое время по требованию субъекта персональных данных. Данное требование должно включать в себя фамилию, имя, отчество (при наличии), контактную информацию (номер телефона, адрес электронной почты или почтовый адрес) субъекта персональных данных, а также перечень персональных данных, обработка которых подлежит прекращению. Указанные в данном требовании персональные данные могут обрабатываться только Оператором, которому оно направлено.</p>
                <p><strong>5.8.4.</strong>&nbsp;Согласие на обработку персональных данных, разрешенных для распространения, прекращает свое действие с момента поступления Оператору требования, указанного в п. 5.8.3 настоящей Политики в отношении обработки персональных данных.<br><br></p>
                <ol start="6">
                    <li><strong> Принципы обработки персональных данных</strong></li>
                </ol>
                <p><strong>6.1.</strong>&nbsp;Обработка персональных данных осуществляется на законной и справедливой основе.</p>
                <p><strong>6.2.&nbsp;</strong>Обработка персональных данных ограничивается достижением конкретных, заранее определенных и законных целей. Не допускается обработка персональных данных, несовместимая с целями сбора персональных данных.</p>
                <p><strong>6.3.</strong>&nbsp;Не допускается объединение баз данных, содержащих персональные данные, обработка которых осуществляется в целях, несовместимых между собой.</p>
                <p><strong>6.4.</strong>&nbsp;Обработке подлежат только персональные данные, которые отвечают целям их обработки.</p>
                <p><strong>6.5.&nbsp;</strong>Содержание и объем обрабатываемых персональных данных соответствуют заявленным целям обработки. Не допускается избыточность обрабатываемых персональных данных по отношению к заявленным целям их обработки.</p>
                <p><strong>6.6.</strong>&nbsp;При обработке персональных данных обеспечивается точность персональных данных, их достаточность, а в необходимых случаях и актуальность по отношению к целям обработки персональных данных. Оператор принимает необходимые меры и/или обеспечивает их принятие по удалению или уточнению неполных или неточных данных.</p>
                <p><strong>6.7.&nbsp;</strong>Хранение персональных данных осуществляется в форме, позволяющей определить субъекта персональных данных, не дольше, чем этого требуют цели обработки персональных данных, если срок хранения персональных данных не установлен федеральным законом, договором, стороной которого, выгодоприобретателем или поручителем по которому является субъект персональных данных. Обрабатываемые персональные данные уничтожаются либо обезличиваются по достижении целей обработки или в случае утраты необходимости в достижении этих целей, если иное не предусмотрено федеральным законом.<br><br></p>
                <ol start="7">
                    <li><strong> Цели обработки персональных данных</strong></li>
                </ol>
                <p><strong>7.1. Цель обработки персональных данных Пользователя:</strong></p>
                <p><strong>7.1.1.</strong>&nbsp;Информирование Пользователя посредством отправки электронных писем;</p>
                <p><strong>7.1.2</strong>.Заключение, исполнение и прекращение гражданско-правовых договоров;</p>
                <p><strong>7.1.3.</strong>&nbsp;Предоставление доступа Пользователю к сервисам, информации и/или материалам, содержащимся на веб-сайте.</p>
                <p><strong>7.2.&nbsp;</strong>Также Оператор имеет право направлять Пользователю уведомления о новых продуктах и услугах, специальных предложениях и различных событиях. Пользователь всегда может отказаться от получения информационных сообщений, направив Оператору письмо на Адрес электронной почты.</p>
                <p><strong>7.3.&nbsp;</strong>Обезличенные данные Пользователей, собираемые с помощью сервисов интернет-статистики, служат для сбора информации о действиях Пользователей на сайте, улучшения качества сайта и его содержания.<br><br></p>
                <ol start="8">
                    <li><strong> Правовые основания обработки персональных данных</strong></li>
                </ol>
                <p><strong>8.1.&nbsp;</strong>Правовыми основаниями обработки персональных данных Оператором являются:</p>
                <p><strong>8.1.1.</strong>&nbsp;Договоры, заключаемые между Оператором и субъектом персональных данных;</p>
                <p><strong>8.1.2.&nbsp;</strong>Федеральные законы, иные нормативно-правовые акты в сфере защиты персональных данных;</p>
                <p><strong>8.2.&nbsp;</strong>Оператор обрабатывает персональные данные Пользователя только в случае их заполнения и/или отправки Пользователем самостоятельно через специальные формы, расположенные на сайте или направленные Оператору посредством электронной почты. Заполняя соответствующие формы и/или отправляя свои персональные данные Оператору, Пользователь выражает свое согласие с данной Политикой.</p>
                <p><strong>8.3.&nbsp;</strong>Оператор обрабатывает обезличенные данные о Пользователе в случае, если это разрешено в настройках браузера Пользователя (включено сохранение файлов и использование технологии JavaScript).</p>
                <p><strong>8.4.&nbsp;</strong>Субъект персональных данных самостоятельно принимает решение о предоставлении его персональных данных и дает согласие свободно, своей волей и в своем интересе.<br><br></p>
                <ol start="9">
                    <li><strong> Условия обработки персональных данных</strong></li>
                </ol>
                <p><strong>9.1.&nbsp;</strong>Обработка персональных данных осуществляется с согласия субъекта персональных данных на обработку его персональных данных.</p>
                <p><strong>9.2.</strong>&nbsp;Обработка персональных данных необходима для достижения целей, предусмотренных международным договором Российской Федерации или законом, для осуществления возложенных законодательством Российской Федерации на оператора функций, полномочий и обязанностей.</p>
                <p><strong>9.3.</strong>&nbsp;Обработка персональных данных необходима для осуществления правосудия, исполнения судебного акта, акта другого органа или должностного лица, подлежащих исполнению в соответствии с законодательством Российской Федерации об исполнительном производстве.</p>
                <p><strong>9.4.</strong>&nbsp;Обработка персональных данных необходима для исполнения договора, стороной которого либо выгодоприобретателем или поручителем по которому является субъект персональных данных, а также для заключения договора по инициативе субъекта персональных данных или договора, по которому субъект персональных данных будет являться выгодоприобретателем или поручителем.</p>
                <p><strong>9.5.</strong>&nbsp;Обработка персональных данных необходима для осуществления прав и законных интересов оператора или третьих лиц либо для достижения общественно значимых целей при условии, что при этом не нарушаются права и свободы субъекта персональных данных.</p>
                <p><strong>9.6.</strong>&nbsp;Осуществляется обработка персональных данных, доступ неограниченного круга лиц к которым предоставлен субъектом персональных данных либо по его просьбе (далее &ndash;&nbsp;общедоступные персональные данные).</p>
                <p><strong>9.7.</strong>&nbsp;Осуществляется обработка персональных данных, подлежащих опубликованию или обязательному раскрытию в соответствии с федеральным законом.<br><br></p>
                <ol start="10">
                    <li><strong> Порядок сбора, хранения, передачи и других видов обработки персональных данных</strong></li>
                </ol>
                <p><strong>10.1.</strong>&nbsp;Оператор обеспечивает сохранность персональных данных и принимает все возможные меры, исключающие доступ к персональным данным неуполномоченных лиц.</p>
                <p><strong>10.2.&nbsp;</strong>Персональные данные Пользователя никогда, ни при каких условиях не будут переданы третьим лицам, за исключением случаев, связанных с исполнением действующего законодательства либо в случае, если субъектом персональных данных дано согласие Оператору на передачу данных третьему лицу для исполнения обязательств по гражданско-правовому договору.</p>
                <p><strong>10.3.&nbsp;</strong>В случае выявления неточностей в персональных данных, Пользователь может актуализировать их самостоятельно, путем направления Оператору уведомление на адрес электронной почты Оператора&nbsp;<span>biz@pirogi.ru</span>&nbsp;с пометкой &laquo;Актуализация персональных данных&raquo;.</p>
                <p><strong>10.4.&nbsp;</strong>Срок обработки персональных данных определяется достижением целей, для которых были собраны персональные данные, если иной срок не предусмотрен договором или действующим законодательством. Пользователь может в любой момент отозвать свое согласие на обработку персональных данных, направив Оператору уведомление посредством электронной почты на электронный адрес почты Оператора&nbsp;<span>biz@pirogi.ru</span>&nbsp;с пометкой &laquo;Отзыв согласия на обработку персональных данных&raquo;.</p>
                <p><strong>10.5.</strong>&nbsp;Вся информация, которая собирается сторонними сервисами, в том числе платежными системами, средствами связи и другими поставщиками услуг, хранится и обрабатывается указанными лицами (Операторами) в соответствии с их Пользовательским соглашением и Политикой конфиденциальности. Субъект персональных данных и/или Пользователь обязан самостоятельно своевременно ознакомиться с указанными документами. Оператор не несет ответственность за действия третьих лиц, в том числе указанных в настоящем пункте поставщиков услуг.</p>
                <p><strong>10.6.</strong>&nbsp;Установленные субъектом персональных данных запреты на передачу (кроме предоставления доступа), а также на обработку или условия обработки (кроме получения доступа) персональных данных, разрешенных для распространения, не действуют в случаях обработки персональных данных в государственных, общественных и иных публичных интересах, определенных законодательством РФ.</p>
                <p><strong>10.7.</strong>&nbsp;Оператор при обработке персональных данных обеспечивает конфиденциальность персональных данных.</p>
                <p><strong>10.8.&nbsp;</strong>Оператор осуществляет хранение персональных данных в форме, позволяющей определить субъекта персональных данных, не дольше, чем этого требуют цели обработки персональных данных, если срок хранения персональных данных не установлен федеральным законом, договором, стороной которого, выгодоприобретателем или поручителем по которому является субъект персональных данных.</p>
                <p><strong>10.9.</strong>&nbsp;Условием прекращения обработки персональных данных может являться достижение целей обработки персональных данных, истечение срока действия согласия субъекта персональных данных или отзыв согласия субъектом персональных данных, а также выявление неправомерной обработки персональных данных.<br><br></p>
                <ol start="11">
                    <li><strong> Перечень действий, производимых Оператором с полученными персональными данными</strong></li>
                </ol>
                <p><strong>11.1.</strong>&nbsp;Оператор осуществляет сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, передачу (распространение, предоставление, доступ), обезличивание, блокирование, удаление и уничтожение персональных данных.</p>
                <p><strong>11.2.</strong>&nbsp;Оператор осуществляет автоматизированную обработку персональных данных с получением и/или передачей полученной информации по информационно-телекоммуникационным сетям или без таковой.<br><br></p>
                <ol start="12">
                    <li><strong> Трансграничная передача персональных данных</strong></li>
                </ol>
                <p><strong>12.1.</strong>&nbsp;Оператор до начала осуществления трансграничной передачи персональных данных обязан убедиться в том, что иностранным государством, на территорию которого предполагается осуществлять передачу персональных данных, обеспечивается надежная защита прав субъектов персональных данных.</p>
                <p><strong>12.2.</strong>&nbsp;Трансграничная передача персональных данных на территории иностранных государств, не отвечающих вышеуказанным требованиям, может осуществляться только в случае наличия согласия в письменной форме субъекта персональных данных на трансграничную передачу его персональных данных и/или исполнения договора, стороной которого является субъект персональных данных.<br><br></p>
                <ol start="13">
                    <li><strong> Конфиденциальность персональных данных</strong></li>
                </ol>
                <p><strong>13.1.</strong>&nbsp;Оператор и иные лица, получившие доступ к персональным данным, обязаны не раскрывать третьим лицам и не распространять персональные данные без согласия субъекта персональных данных, если иное не предусмотрено федеральным законом.<br><br></p>
                <ol start="14">
                    <li><strong> Заключительные положения</strong></li>
                </ol>
                <p><strong>14.1.</strong>&nbsp;Пользователь может получить любые разъяснения по&nbsp;интересующим вопросам, касающимся обработки его персональных данных, обратившись к&nbsp;Оператору с&nbsp;помощью электронной почты&nbsp;<span>biz@pirogi.ru</span>.</p>
                <p><strong>14.2</strong>. В данном документе будут отражены любые изменения политики обработки персональных данных Оператором. Политика действует бессрочно до замены ее новой версией.</p>
                <p><strong>14.3</strong> Актуальная версия Политики в&nbsp;свободном доступе расположена в&nbsp;сети Интернет по&nbsp;адресу&nbsp;<span>https://pirogi.ru/privacy</span>.<br><br></p>    </div>
        </div>
    </div>
